SourceCode.Declaration:
/// <summary>
/// Chain of Command extension on <c>DirPerson</c> to detect person name, alias, gender, language,
/// or primary phone/email pointer updates and resolve linked <c>CustTable</c> records in company 'utc'.
/// </summary>
[ExtensionOf(tableStr(DirPerson))]
public final class UTCSFDirPerson_Extension
{
}

Method.Source:
public void update()
{
    DirPerson origPerson        = this.orig();
    boolean   hasRelevantChange = (this.Name                != origPerson.Name
                                || this.NameAlias           != origPerson.NameAlias
                                || this.Gender              != origPerson.Gender
                                || this.LanguageId          != origPerson.LanguageId
                                || this.PrimaryContactPhone != origPerson.PrimaryContactPhone
                                || this.PrimaryContactEmail != origPerson.PrimaryContactEmail);

    next update();

    if (hasRelevantChange)
    {
        UTCSFCustomerChangeHandler::tryEnqueueByPartyRecId(this.RecId);
    }
}
